insert into public.desk_rows (tier, feature, row_key, "row", record_text, snapshot_at) values ('global', 'Global Aid', '06b0a03512328adf5cd84449', '{"__gaId":"gho26","title":"UN Global Humanitarian Appeal 2026","name":"UN Global Humanitarian Appeal 2026","agency":"UN OCHA","region":"Global","geography":"23 country operations + 6 regional/refugee plans","programme_type":"Inter-agency appeal","type":"Inter-agency appeal","appeal_status":"Active appeal","requirement":33000000000,"coverageComparable":"true","people_target":135000000,"period":"2026","dataThrough":"08 Dec 2025","latestDate":"08 Dec 2025","latest":"The UN and aid partners launched a $33 billion appeal to support 135 million people through 23 country operations and six refugee or migrant plans.","brief":"The 2026 appeal is the top-level humanitarian financing benchmark. The analytical priority is funding conversion into country plans, because the launch figure is a requirement—not cash received.","source_url":"https://www.un.org/sg/en/content/highlight/2025-12-08.html","source_label":"United Nations","fundingNote":"Funding receipts must be reconciled against the live OCHA Financial Tracking Service.","sectors_json":"[\"Food security\",\"Health\",\"WASH\",\"Shelter\",\"Protection\",\"Education\"]","delivery":"UN-coordinated country and regional response plans","coordinator":"UN OCHA with UN agencies and humanitarian partners","indicators_json":"[[\"Country operations\",23,\"23\"],[\"Regional / refugee plans\",6,\"6\"]]","milestones_json":"[[\"08 Dec 2025\",\"2026 global appeal launched\"],[\"2026\",\"Funding and delivery tracked through OCHA FTS and country plans\"]]"}'::jsonb, '__gaId: gho26
