insert into public.desk_rows (tier, feature, row_key, "row", record_text, snapshot_at) values ('global', 'Global Aid', '55aa9bbf00f171ab94ed6505', '{"__gaId":"unicef26","title":"UNICEF Humanitarian Action for Children 2026","name":"UNICEF Humanitarian Action for Children 2026","agency":"UNICEF","region":"Global","geography":"35 country, multi-country, regional and global appeals","programme_type":"Child-focused appeal","type":"Child-focused appeal","appeal_status":"Active appeal","requirement":7660000000,"coverageComparable":"true","people_target":73000000,"period":"2026","dataThrough":"Dec 2025","latestDate":"Dec 2025","latest":"UNICEF opened 35 humanitarian appeals requiring $7.66 billion to assist more than 73 million vulnerable children, families and caregivers.","brief":"This is a portfolio of child-centred emergency programmes rather than one undifferentiated fund. Monitor funding by country appeal and by service line: health, nutrition, WASH, education and child protection.","source_url":"https://www.unicef.org/appeals","source_label":"UNICEF HAC","fundingNote":"Current receipts are published in country situation reports and should not be inferred from the appeal requirement.","sectors_json":"[\"Health\",\"Nutrition\",\"WASH\",\"Education\",\"Child protection\",\"Social protection\"]","delivery":"UNICEF country offices with government and implementing partners","coordinator":"UNICEF","indicators_json":"[[\"Country appeals\",23,\"23\"],[\"Multi-country appeals\",4,\"4\"],[\"Regional appeals\",7,\"7\"],[\"Global support appeal\",1,\"1\"]]","milestones_json":"[[\"Dec 2025\",\"2026 HAC portfolio published\"],[\"2026\",\"Country situation reports update funding and delivery\"]]"}'::jsonb, '__gaId: unicef26
